window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f2fd756bb50418fa"]={"versions": [{"id": "FIG-f2fd756bb50418fa", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Feature-Modell / Feature-Baum (Feature-Dekompositionsdiagramm nach FODA-Konvention / Feature-Oriented Domain Analysis).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, Release R24-11). Das Diagramm spezifiziert die strukturelle Zerlegung des übergeordneten Features <code>FO_TR_FEAT_00097</code> (<em>Vehicle Domain Interfaces</em>, VDI) in standardisierte domänenspezifische Schnittstellenpakete. Zweck ist die herstellerübergreifende Vereinheitlichung funktionaler Applikationsschnittstellen (SWC-Ports, Datentypen, Semantiken) über Classic und Adaptive Platform hinweg.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelknoten (Parent Feature):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00097</code> (<em>Vehicle_Domain_Interfaces</em>): Übergreifende Klammer für standardisierte Fahrzeugdomänen-Schnittstellen.\n</li></ul>\n</li><li><strong>Kindknoten (Sub-Features / Domänen):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00106</code> (<em>Fuel_Cell</em>): Schnittstellen für Brennstoffzellensysteme und H2-spezifische Subsysteme.\n</li><li><code>FO_TR_FEAT_00104</code> (<em>Occupant_And_Pedestrian_Safety_Systems</em>): Schnittstellen für Insassen- und Fußgängerschutz (Airbags, Crash-Sensorik, Pre-Crash).\n</li><li><code>FO_TR_FEAT_00105</code> (<em>Powertrain</em>): Schnittstellen für konventionelle, hybride und elektrische Antriebsstränge.\n</li><li><code>FO_TR_FEAT_00102</code> (<em>Chassis</em>): Schnittstellen für Fahrwerksregelung, Lenkung, Brems- und Stabilitätssysteme.\n</li><li><code>FO_TR_FEAT_00098</code> (<em>ADAS</em>): Schnittstellen für Fahrerassistenzsysteme und Umfeldsensorik/-aktionspfade.\n</li><li><code>FO_TR_FEAT_00101</code> (<em>Body_And_Comfort</em>): Schnittstellen für Karosserieelektronik, Komfort- und Klimasysteme.\n</li><li><code>FO_TR_FEAT_00103</code> (<em>HMI_Multimedia_And_Telematics</em>): Schnittstellen für Mensch-Maschine-Interaktion, Infotainment und Konnektivität.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li>Hierarchische 1:n-Dekomposition.\n</li><li><strong>FODA-Konnektoren:</strong> Alle Kanten enden am Zielknoten mit einem ungefüllten Kreis (<em>Open Circle</em>). Dies deklariert sämtliche 7 Sub-Features formal als <strong>optionale Features</strong> bezogen auf den Wurzelknoten (Kardinalität <code>[0..1]</code> je Domäne).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Rein statische Feature-Taxonomie / Metamodell-Abgrenzung. Es existieren keine Zustandswechsel, Ausführungssequenzen oder Laufzeittrigger.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Modellierung &amp; SWC-Design:</strong> Entwickler von Applikations-SWCs (Classic) bzw. Adaptive Applications binden gezielt die zugehörigen VDI-ARXML-Blueprints (Port-Interfaces, Signal-Datentypen, CompuMethods, Units) ein. Die optionale Kardinalität erlaubt schlanke Systembeschreibungen ohne Overhead irrelevanter Domänen.\n</li><li><strong>Portabilität &amp; Cross-Platform:</strong> Die referenzierten VDI-Definitionen standardisieren Sender-Receiver- und Client-Server-Interfaces unabhängig von der Ziel-Middleware (RTE unter CP bzw. <code>ara::com</code> / Service-Interfaces unter AP).\n</li><li><strong>Keine BSW-/MCAL-Wirkung:</strong> Das Feature erzeugt keine direkten C-APIs für Treiber oder BSW-Stacks, sondern steuert die Standardisierung der VFB-Kommunikationsmatrix (Virtual Functional Bus) auf Applikationsebene.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-92bd53d7c814e234", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Feature-Modell / Feature-Baum (Feature-Dekompositionsdiagramm nach FODA-Konvention / Feature-Oriented Domain Analysis).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>, Release R24-11). Das Diagramm spezifiziert die strukturelle Zerlegung des übergeordneten Features <code>FO_TR_FEAT_00097</code> (<em>Vehicle Domain Interfaces</em>, VDI) in standardisierte domänenspezifische Schnittstellenpakete. Zweck ist die herstellerübergreifende Vereinheitlichung funktionaler Applikationsschnittstellen (SWC-Ports, Datentypen, Semantiken) über Classic und Adaptive Platform hinweg.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelknoten (Parent Feature):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00097</code> (<em>Vehicle_Domain_Interfaces</em>): Übergreifende Klammer für standardisierte Fahrzeugdomänen-Schnittstellen.\n</li></ul>\n</li><li><strong>Kindknoten (Sub-Features / Domänen):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00106</code> (<em>Fuel_Cell</em>): Schnittstellen für Brennstoffzellensysteme und H2-spezifische Subsysteme.\n</li><li><code>FO_TR_FEAT_00104</code> (<em>Occupant_And_Pedestrian_Safety_Systems</em>): Schnittstellen für Insassen- und Fußgängerschutz (Airbags, Crash-Sensorik, Pre-Crash).\n</li><li><code>FO_TR_FEAT_00105</code> (<em>Powertrain</em>): Schnittstellen für konventionelle, hybride und elektrische Antriebsstränge.\n</li><li><code>FO_TR_FEAT_00102</code> (<em>Chassis</em>): Schnittstellen für Fahrwerksregelung, Lenkung, Brems- und Stabilitätssysteme.\n</li><li><code>FO_TR_FEAT_00098</code> (<em>ADAS</em>): Schnittstellen für Fahrerassistenzsysteme und Umfeldsensorik/-aktionspfade.\n</li><li><code>FO_TR_FEAT_00101</code> (<em>Body_And_Comfort</em>): Schnittstellen für Karosserieelektronik, Komfort- und Klimasysteme.\n</li><li><code>FO_TR_FEAT_00103</code> (<em>HMI_Multimedia_And_Telematics</em>): Schnittstellen für Mensch-Maschine-Interaktion, Infotainment und Konnektivität.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li>Hierarchische 1:n-Dekomposition.\n</li><li><strong>FODA-Konnektoren:</strong> Alle Kanten enden am Zielknoten mit einem ungefüllten Kreis (<em>Open Circle</em>). Dies deklariert sämtliche 7 Sub-Features formal als <strong>optionale Features</strong> bezogen auf den Wurzelknoten (Kardinalität <code>[0..1]</code> je Domäne).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Rein statische Feature-Taxonomie / Metamodell-Abgrenzung. Es existieren keine Zustandswechsel, Ausführungssequenzen oder Laufzeittrigger.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Modellierung &amp; SWC-Design:</strong> Entwickler von Applikations-SWCs (Classic) bzw. Adaptive Applications binden gezielt die zugehörigen VDI-ARXML-Blueprints (Port-Interfaces, Signal-Datentypen, CompuMethods, Units) ein. Die optionale Kardinalität erlaubt schlanke Systembeschreibungen ohne Overhead irrelevanter Domänen.\n</li><li><strong>Portabilität &amp; Cross-Platform:</strong> Die referenzierten VDI-Definitionen standardisieren Sender-Receiver- und Client-Server-Interfaces unabhängig von der Ziel-Middleware (RTE unter CP bzw. <code>ara::com</code> / Service-Interfaces unter AP).\n</li><li><strong>Keine BSW-/MCAL-Wirkung:</strong> Das Feature erzeugt keine direkten C-APIs für Treiber oder BSW-Stacks, sondern steuert die Standardisierung der VFB-Kommunikationsmatrix (Virtual Functional Bus) auf Applikationsebene.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f2fd756bb50418fa", "to": "FIG-92bd53d7c814e234", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
